"""Original pneumonia chapter: presentation, severity, microbiology and stewardship."""
from qbank_authoring import question,ref,finalize
CA=ref('ATS/IDSA: Diagnosis and Treatment of Adults with CAP, 2019','https://www.idsociety.org/globalassets/idsa/practice-guidelines/community-acquired-pneumonia-in-adults/executive_summary.pdf')
UP=ref('ATS: Diagnosis and Management of CAP, 2025','https://doi.org/10.1164/rccm.202507-1692ST')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An adult has acute cough, fever, focal crackles and a new lobar opacity. Which finding best supports pneumonia rather than uncomplicated acute bronchitis?', 'A new pulmonary infiltrate in the compatible clinical setting',[
 ('Purulent sputum alone','Sputum color does not establish pneumonia or a bacterial cause.'),('An elevated CRP alone','Inflammation has multiple infectious and noninfectious causes.'),('Wheeze that improves with bronchodilator','This can accompany airway disease without parenchymal infection.')],
 'Integrate the syndrome with imaging', '**Pneumonia is a parenchymal infection diagnosed from compatible clinical and imaging findings.**',['A single symptom is not sufficiently discriminatory.','Heart failure, infarction and organizing pneumonia can mimic an infiltrate.'], '**Judge severity and alternative diagnoses at the same time.**',['Use chest radiography or an appropriate alternative when indicated.','Lung ultrasound can be useful with adequate expertise and infrastructure.'],[['Bronchitis','No established new parenchymal infiltrate'],['Pneumonia','Compatible syndrome plus infiltrate'],['Mimics','Require clinical correlation']],[CA,UP],style='clinical_scenario')
q('Which statement best describes the role of the Pneumonia Severity Index in adult CAP?', 'It supports the hospitalization decision alongside clinical judgment and practical care needs',[
 ('It determines the causative organism','It estimates prognosis rather than microbial etiology.'),('It replaces assessment of hypoxemia and oral intake','These can alter disposition even with a low numerical risk.'),('It is an automatic indication for antipseudomonal therapy','Drug selection depends on separate epidemiological and microbiological risks.')],
 'A prognostic score assists disposition but is not the entire decision', '**PSI is preferred by ATS/IDSA as a validated mortality prediction aid.**',['Age and comorbidities strongly affect the score.','Functional, social and physiological factors remain relevant.'], '**Reassess patients who appear sicker than their score suggests.**',['Inability to maintain intake or oxygenation can require admission.','Use severe-CAP criteria when considering higher-level care.'],[['PSI','Prognosis and disposition support'],['Clinical assessment','Immediate physiology and care feasibility'],['Microbiology risk','Separate antibiotic decision']],[CA])
q('A 68-year-old with pneumonia is confused, has respiratory rate 32/min, BP 88/56 mmHg and blood urea 10 mmol/L. What is the CURB-65 score?', '5',[
 ('2','All five criteria, not only age and confusion, are present.'),('3','Urea, respiratory rate and hypotension also meet thresholds.'),('4','Age 65 or older contributes the fifth point.')],
 'Count each CURB-65 component once', '**Confusion, urea greater than 7 mmol/L, respiratory rate at least 30, low blood pressure and age at least 65 each contribute one.**',['Low BP means systolic below 90 or diastolic at most 60.','This patient meets all five criteria.'], '**The physiology itself demands urgent escalation.**',['Do not wait for score calculation to treat shock or hypoxemia.','The score estimates risk rather than specifying an organism.'],[['Confusion / urea','1 + 1'],['Respiration / BP','1 + 1'],['Age','1; total 5']],[CA],style='clinical_scenario')
q('Which finding is a major ATS/IDSA criterion for severe community-acquired pneumonia?', 'Septic shock requiring vasopressors',[
 ('Respiratory rate 30/min alone','This is a minor criterion.'),('Multilobar infiltrates alone','This is a minor criterion.'),('Urea nitrogen at least 20 mg/dL alone','This is a minor criterion.')],
 'Distinguish major organ-support needs from minor severity features', '**Either vasopressor-dependent shock or respiratory failure requiring mechanical ventilation establishes a major criterion.**',['Three or more minor criteria can also define severe CAP.','Minor criteria describe physiological and laboratory risk.'], '**Use severity to guide monitoring, microbiology and therapy.**',['A deteriorating patient needs escalation before all criteria accumulate.','Reassess serially rather than assigning severity only at admission.'],[['Major','Vasopressors or mechanical ventilation'],['Minor','Examples: tachypnea, multilobar disease, uremia'],['Threshold','One major or at least three minor']],[CA])
q('Which adult CAP presentation most strongly supports obtaining blood cultures and a lower respiratory specimen?', 'Severe CAP requiring intubation',[
 ('Mild uncomplicated CAP managed as an outpatient','Routine cultures have low yield in this group.'),('An improving outpatient with no resistant-pathogen risk','Routine cultures seldom change management.'),('A resolving isolated viral upper respiratory infection','This is not an indication for pneumonia cultures.')],
 'Diagnostic intensity should match severity and actionable risk', '**Severe CAP warrants microbiological investigation.**',['Obtain specimens promptly without materially delaying urgent treatment.','An endotracheal aspirate is useful after intubation.'], '**Also investigate when MRSA or Pseudomonas coverage is contemplated.**',['Prior isolation and relevant antibiotic/hospital exposure inform risk.','Results support narrowing treatment when appropriate.'],[['Nonsevere outpatient','No routine cultures'],['Severe CAP','Blood and respiratory specimens'],['Expanded coverage','Obtain cultures to guide de-escalation']],[CA],style='clinical_scenario')
q('Which history is the strongest specific reason to consider empiric MRSA coverage in a patient admitted with CAP?', 'Prior respiratory isolation of MRSA',[
 ('Residence in a care facility alone','The abandoned HCAP category should not automatically trigger broad therapy.'),('Diabetes without other risk factors','This is not a specific MRSA indication.'),('Age over 65 alone','Age raises outcome risk but is not a sufficient MRSA predictor.')],
 'Use pathogen-specific risk rather than a broad healthcare label', '**Prior respiratory isolation is a strong actionable predictor.**',['Recent hospitalization with parenteral antibiotics may matter with locally validated risk.','Severe illness affects the threshold for empiric expansion.'], '**Obtain cultures and reassess broad therapy early.**',['Local resistance patterns and clinical context matter.','Do not continue unnecessary coverage after reliable negative evaluation and improvement.'],[['Prior respiratory MRSA','Strong specific risk'],['Care facility alone','Insufficient automatic indication'],['Reassessment','Microbiology and clinical response']],[CA])
q('An immunocompetent adult with nonsevere inpatient CAP has no MRSA or Pseudomonas risk and no relevant drug contraindication. Which regimen is appropriate?', 'Ceftriaxone plus azithromycin',[
 ('Ceftriaxone alone as the preferred standard combination','The recommended beta-lactam/macrolide regimen supplies atypical coverage.'),('Vancomycin alone','It lacks adequate coverage for the routine CAP pathogen spectrum.'),('Ciprofloxacin alone','It is not a preferred respiratory fluoroquinolone for standard CAP.')],
 'Cover typical and relevant atypical pathogens', '**A beta-lactam plus macrolide is a standard inpatient option.**',['A respiratory fluoroquinolone can be an alternative in appropriate nonsevere patients.','Patient-specific contraindications and local guidance influence selection.'], '**Review microbiology, interactions and route as the patient improves.**',['QT risk and other adverse effects require consideration.','Do not add MRSA or antipseudomonal drugs without a reason.'],[['Beta-lactam plus macrolide','Standard inpatient option'],['Respiratory fluoroquinolone','Alternative in selected nonsevere cases'],['Broad resistant-pathogen drugs','Risk-based']],[CA],style='clinical_scenario')
q('A patient has clinically and radiographically established bacterial-appearing CAP but a low initial procalcitonin concentration. What should guide initial treatment?', 'Start indicated empiric antibiotics rather than using the low value alone to withhold them',[
 ('Withhold antibiotics because low procalcitonin excludes bacterial pneumonia','Its sensitivity is insufficient for that rule.'),('Treat only if a repeat value exceeds a fixed threshold','Waiting can delay needed therapy.'),('Use procalcitonin to select a specific bacterial species','It is not an organism-identification test.')],
 'A biomarker cannot overrule an established pneumonia syndrome', '**A low value does not safely exclude bacterial CAP.**',['Timing and pathogen characteristics affect the response.','Interpret it within the clinical context.'], '**Use subsequent evidence for stewardship.**',['Reassess diagnosis, cultures and stability.','Avoid extending therapy solely for an isolated biomarker abnormality.'],[['Low initial value','Not a reliable exclusion'],['Initial therapy','Clinical and imaging diagnosis'],['Follow-up','Integrated reassessment']],[CA],style='clinical_scenario')
q('Following witnessed gastric aspiration during a seizure, a patient develops abrupt hypoxemia and infiltrates but improves substantially within 24–48 hours without persistent infection signs. What is the best initial interpretation?', 'Aspiration pneumonitis from chemical lung injury',[
 ('Established anaerobic lung abscess','Abscess is not explained by this immediate, rapidly resolving course.'),('Chronic aspiration-related bronchiectasis','That is a chronic structural process.'),('Bacterial aspiration pneumonia established by the event alone','Aspiration can cause sterile chemical injury without bacterial infection.')],
 'Distinguish chemical injury from infection', '**The immediate syndrome after gastric aspiration can be inflammatory rather than bacterial.**',['Provide airway and oxygenation support.','Monitor because secondary infection or severe lung injury can occur.'], '**Do not equate every aspiration event with an antibiotic indication.**',['Persistent or later infectious features require reassessment.','Evaluate swallowing and recurrence risk after recovery.'],[['Pneumonitis','Acute chemical injury'],['Pneumonia','Infection requiring treatment'],['Abscess','Necrotizing suppurative complication']],[CA],style='clinical_scenario')
q('In suspected aspiration pneumonia, which additional finding most supports adding specific anaerobic coverage beyond a standard CAP regimen?', 'A lung abscess or empyema',[
 ('Dysphagia alone','Aspiration risk alone does not mandate additional anaerobic drugs.'),('A dependent-lobe opacity without suppuration','Routine additional anaerobic coverage is not recommended on that finding alone.'),('A witnessed aspiration event without infection','Chemical pneumonitis may need supportive care rather than antibiotics.')],
 'Reserve additional anaerobic treatment for the relevant complication', '**Abscess or empyema changes the microbial and source-control assessment.**',['Regimen choice must cover the likely polymicrobial infection.','An infected pleural collection also needs drainage assessment.'], '**Avoid unnecessary redundant coverage in uncomplicated aspiration CAP.**',['Some agents already provide anaerobic activity.','Consider adverse effects, including C. difficile risk.'],[['Uncomplicated aspiration CAP','Standard risk-based regimen'],['Abscess','Anaerobic-active treatment'],['Empyema','Antibiotics plus source control']],[CA])
q('An immunocompetent outpatient with uncomplicated nonsevere CAP is clinically stable after 3 effective antibiotic days. There is no bacteremia, abscess, resistant organism or other reason for prolonged therapy. Which statement reflects the 2025 ATS guidance?', 'A course shorter than 5 days, with a minimum of 3 days, can be considered using daily clinical stability assessment',[
 ('Every CAP episode requires at least 10 days','Routine prolonged treatment is unsupported in this low-risk setting.'),('All antibiotics must stop after a single dose','The updated shorter-course recommendation still has a minimum duration and stability requirement.'),('The same 3-day strategy is established for severe necrotizing MRSA pneumonia','Complicated, severe or specific-pathogen disease requires a different duration assessment.')],
 'Shorter treatment is conditional on clinical response and uncomplicated disease', '**The 2025 update permits selected stable nonsevere patients to receive less than five days, at least three.**',['Effective antibiotic exposure and stability must be established.','Do not apply this to unresolved infection or complications.'], '**Individualize the stop decision rather than using a universal calendar.**',['Check oxygenation, hemodynamics, mentation and oral intake.','Severe CAP and pathogens needing longer therapy are outside this simple scenario.'],[['Selected nonsevere stable CAP','At least 3 days may suffice'],['Severe CAP','At least 5 days under updated guidance'],['Complication / special organism','Individualized longer course']],[UP],style='clinical_scenario')
q('For adult inpatients with severe CAP unrelated to influenza and no major corticosteroid contraindication, which statement reflects the 2025 ATS update?', 'Systemic corticosteroids are conditionally suggested as adjunctive treatment',[
 ('Corticosteroids are recommended routinely for all nonsevere CAP','The update recommends against routine use for nonsevere CAP absent another indication.'),('Corticosteroids replace antibiotic therapy','They are adjunctive rather than antimicrobial treatment.'),('The recommendation automatically includes influenza pneumonia','Influenza pneumonia is excluded from this severe-CAP recommendation.')],
 'Apply the updated recommendation to its intended subgroup', '**Severe noninfluenza CAP may benefit from adjunctive systemic corticosteroids.**',['The recommendation is conditional, not a mandate for every patient.','Consider timing, hyperglycemia, infection risks and contraindications.'], '**Do not generalize across severity or etiology.**',['Routine steroids are not recommended for nonsevere CAP.','Other indications, such as asthma or refractory shock, require separate assessment.'],[['Severe noninfluenza CAP','Conditional adjunctive steroids'],['Nonsevere CAP','No routine steroids'],['Influenza CAP','Excluded from this recommendation']],[UP])
q('An inpatient with severe radiographic CAP has a positive influenza PCR. Which approach to antibacterial treatment is most appropriate initially?', 'Treat possible bacterial coinfection while also providing indicated antiviral therapy',[
 ('Exclude bacterial infection because a virus was detected','Viral and bacterial infections can coexist.'),('Give antibacterial therapy but omit influenza treatment in severe disease','Antiviral therapy remains important.'),('Delay all treatment until paired serology returns','Severe illness requires timely treatment.')],
 'A positive viral test does not exclude bacterial coinfection in severe CAP', '**Initial treatment must account for both processes.**',['Use appropriate specimens and local epidemiology.','Influenza may be complicated by pneumococcal or staphylococcal infection.'], '**Reassess antibacterial need as evidence accumulates.**',['Severity and bacterial evidence affect de-escalation.','Do not import noninfluenza CAP steroid recommendations into influenza pneumonia.'],[['Virus detected','Etiological information, not exclusion of bacteria'],['Severe CAP','Initial coinfection coverage'],['Later course','Microbiology-guided reassessment']],[UP,CA],style='clinical_scenario')
q('A CAP patient remains febrile and hypoxemic after an initially appropriate regimen. What is the best next principle?', 'Reassess for complications, resistant or alternative pathogens, and noninfectious mimics',[
 ('Change to the broadest regimen without additional assessment','This can miss source-control problems or an incorrect diagnosis.'),('Assume radiographic opacity must clear within 48 hours','Radiographic recovery often lags behind clinical recovery.'),('Stop evaluation because the initial diagnosis was pneumonia','Failure to improve requires a renewed diagnostic assessment.')],
 'Nonresponse is a diagnostic problem as well as a drug problem', '**Check the original diagnosis, delivery of therapy and new complications.**',['Empyema, obstruction and abscess may require procedures.','PE, edema and inflammatory lung disease may mimic infection.'], '**Use targeted imaging and microbiology to guide the next step.**',['Review host immune status and travel/exposure history.','Avoid indiscriminate escalation that delays the necessary intervention.'],[['Infection problem','Resistance, wrong pathogen or inadequate delivery'],['Complication','Collection, necrosis or obstruction'],['Mimic','Vascular, cardiac or inflammatory disease']],[CA],style='clinical_scenario')
q('Repeated pneumonia affects the same lobe in an older smoker. Which investigation principle is most important after acute stabilization?', 'Assess for an obstructing endobronchial lesion',[
 ('Assume recurrent viral infections without anatomical evaluation','A repeated focal distribution suggests a local cause.'),('Diagnose primary immunodeficiency from the distribution alone','Immune defects can cause infections but do not specifically explain a fixed lobar recurrence.'),('Exclude cancer because antibiotics temporarily improved symptoms','Postobstructive infection can improve while the lesion persists.')],
 'Recurrent infection in one anatomical territory suggests obstruction', '**A tumor, foreign body or localized stenosis may impair clearance.**',['CT helps define the lesion and distal changes.','Bronchoscopy may be required for direct assessment and tissue.'], '**Treat infection while addressing its cause.**',['Clinical improvement does not exclude malignancy.','Follow persistent or recurrent abnormalities according to risk.'],[['Same lobe','Local obstruction or structural lesion'],['Multiple territories','Consider broader host and airway causes'],['Temporary response','Does not remove an obstructing cause']],[CA],style='clinical_scenario')
q('A previously healthy adult has nonsevere CAP suitable for outpatient care, no major comorbidity and no relevant allergy. Local pneumococcal macrolide resistance is 35%. Which option is appropriate?', 'Amoxicillin',[
 ('Azithromycin monotherapy as the default despite the resistance rate','Macrolide monotherapy is reserved for settings with pneumococcal resistance below 25% under ATS/IDSA guidance.'),('Vancomycin monotherapy','This is unnecessarily broad for MRSA and incomplete for routine outpatient CAP.'),('Metronidazole monotherapy','It does not cover the routine CAP pathogen spectrum.')],
 'Outpatient therapy depends on comorbidity and resistance', '**Amoxicillin is a standard option for a low-risk outpatient.**',['Doxycycline is another recommended option in appropriate patients.','Comorbidities can change the recommended regimen.'], '**Use local susceptibility rather than habit to choose a macrolide.**',['Evaluate pregnancy, allergy and interactions.','Provide follow-up instructions for deterioration or failure to improve.'],[['Low-risk outpatient','Amoxicillin or appropriate alternative'],['Macrolide alone','Only with sufficiently low local resistance'],['Comorbidity','May require broader combination or alternative']],[CA],style='clinical_scenario')
